import http from 'http';
function main(): void {
  const srv = http.createServer((req: any, res: any) => { res.end('x'); });
  const out: string[] = [];
  out.push('on:' + (srv.on('listening', () => {}) === srv));
  out.push('ref:' + (srv.ref() === srv));
  srv.listen(0, '127.0.0.1', () => {
    out.push('close:' + (srv.close() === srv));
  });
  setTimeout(() => console.log(out.join(',')), 300);
}
